208	      }).then(() => undefined),
209	    ),
210	    subscribe("member.invited", (payload) =>
211	      record(payload.orgId, "member.invited", {
212	        actorId: payload.actorId,
213	        subjectKind: "member",
214	        subjectId: payload.email,
215	        projectId: null,
216	        summary: `Invited ${payload.email} as ${payload.role}`,
