/** Refuses a time range whose end is before its start; both ends are inclusive. */
function assertValidRange(
  since: IsoTimestamp | undefined,
  until: IsoTimestamp | undefined,
): void {
  if (since === undefined || until === undefined) return;
  if (new Date(until).getTime() < new Date(since).getTime()) {
    throw new Error("The range's until cannot be before its since");
  }
}

