/** Looks up the project a comment's issue belongs to, for the audit row's project column. */
async function findProjectIdForIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<ProjectId | null> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  return issue?.projectId ?? null;
}

async function recordCommentActivity(
  orgId: OrgId,
  action: "comment.created" | "comment.updated" | "comment.deleted",
  payload: {
    actorId: UserId | null;
    commentId: CommentId;
    issueId: IssueId;
    occurredAt: IsoTimestamp;
  },
  summary: string,
): Promise<void> {
  await record(orgId, action, {
    actorId: payload.actorId,
    subjectKind: "comment",
    subjectId: payload.commentId,
    projectId: await findProjectIdForIssue(orgId, payload.issueId),
    summary,
    occurredAt: payload.occurredAt,
  });
}

